// ==================== 房东模拟器 - 变量结构定义 ====================
// 使用 MVU Zod 定义变量结构
// 注意：这个脚本必须在 01_MVU本体.js 之后加载

import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// ==================== Schema 定义 ====================
// 使用 zod 4 的语法定义变量结构
// z 是全局变量，由 MVU 本体提供

// ==================== 房间子Schema（含业务保护 + prefault） ====================
const RoomSchema = z.object({
    类型: z.string().prefault('空房间'),
    名称: z.string().prefault('未命名房间'),
    楼层: z.string().prefault('一楼'),
    位置: z.string().prefault('1-2'),
    住户: z.string().prefault('无'),
    描述: z.string().prefault('暂无描述'),
}).prefault({}).refine(room => {
    // 业务保护：有租客居住的房间类型必须为"卧室"
    const occupants = room.住户.split('、').map(s => s.trim()).filter(s => s && s !== '无' && s !== '<user>' && s !== '{{user}}');
    if (occupants.length > 0 && room.类型 !== '卧室' && room.类型 !== '您的房间') return false;
    return true;
}, { message: '有租客居住的房间类型必须为"卧室"，不能将租客分配到非卧室房间' });

const Schema = z.object({
    // 世界时间
    世界: z.object({
        年份: z.string().prefault('2024'),
        日期: z.string().prefault('1月1日'),
        星期: z.string().prefault('星期一'),
        时间: z.string().prefault('上午'),
    }).prefault({}),

    // 公寓配置
    公寓: z.object({
        楼层列表: z.array(z.string()).prefault([]),
        房间列表: z.record(
            z.string().describe('房间名'),
            RoomSchema
        ).prefault({}),
    }).prefault({}),

    // 租客列表（动态键：租客姓名 -> 租客数据）
    // 只保留核心字段：年龄、外貌、职业、性格、状态、内心、关系
    租客列表: z.record(
        z.string().describe('租客姓名'),
        z.object({
            年龄: z.coerce.number().prefault(20),
            外貌: z.string().prefault('待描述'),
            职业: z.string().prefault('无'),
            性格: z.string().prefault('待描述'),
            状态: z.string().prefault('正常'),
            内心: z.string().prefault('平静'),
            关系: z.record(
                z.string().describe('对象名'),
                z.string().describe('关系描述')
            ).prefault({}),
        }).prefault({})
    ).prefault({}),

    // 大富翁变量
    大富翁: z.object({
        筹码: z.coerce.number().transform(v => Math.max(v, 0)).prefault(5000),
        回合: z.coerce.number().prefault(0),
        位置: z.coerce.number().prefault(0),
        据点: z.record(
            z.string().describe('格子ID'),
            z.object({
                光顾次数: z.coerce.number().prefault(0),
                投资额: z.coerce.number().prefault(0),
                等级: z.coerce.number().prefault(0),
            }).prefault({})
        ).prefault({}),
        队伍: z.array(z.string()).prefault([]),
        道具: z.record(
            z.string().describe('道具名'),
            z.coerce.number().prefault(0)
        ).prefault({}),
        监狱回合: z.coerce.number().prefault(0),
        最近事件: z.array(z.string()).prefault([]),
    }).prefault({}),

    // 分基地（简化版房产）
    分基地: z.record(
        z.string().describe('基地名'),
        z.object({
            描述: z.string().prefault(''),
            住户: z.array(z.string()).prefault([]),
        }).prefault({})
    ).prefault({}),
}).superRefine((data, ctx) => {
    // ==================== 跨字段一致性校验 ====================
    const tenantNames = new Set(Object.keys(data.租客列表 || {}));
    const rooms = data.公寓?.房间列表 || {};

    // 校验1：房间住户必须存在于租客列表（防止幽灵住户）
    for (const [roomKey, room] of Object.entries(rooms)) {
        const occupant = room.住户;
        if (!occupant || occupant === '无') continue;
        if (room.类型 === '您的房间') continue;
        const names = occupant.split('、').map(s => s.trim()).filter(s => s && s !== '无' && s !== '<user>' && s !== '{{user}}');
        for (const name of names) {
            if (!tenantNames.has(name)) {
                ctx.addIssue({
                    code: 'custom',
                    message: '房间「' + roomKey + '」的住户「' + name + '」不在租客列表中，请同时添加租客档案',
                    path: ['公寓', '房间列表', roomKey, '住户'],
                });
            }
        }
    }

    // 校验2：租客列表中的每个租客必须被分配到某间卧室（防止无房租客）
    for (const tenantName of tenantNames) {
        let found = false;
        for (const room of Object.values(rooms)) {
            const names = (room.住户 || '').split('、').map(s => s.trim());
            if (names.includes(tenantName)) { found = true; break; }
        }
        if (!found) {
            ctx.addIssue({
                code: 'custom',
                message: '租客「' + tenantName + '」未分配到任何房间，请更新对应卧室的住户字段',
                path: ['租客列表', tenantName],
            });
        }
    }
});

// ==================== 注册 Schema ====================
$(() => {
    registerMvuSchema(Schema);
    console.log('✅ 房东模拟器变量结构已注册');
});

/**
 * 悬浮球菜单管理器 - 统一管理多个悬浮球功能
 *
 * 功能：
 * - 创建主悬浮球（菜单按钮）
 * - 管理子悬浮球（功能球）
 * - 展开/收起动画
 * - 拖拽支持
 * - 位置持久化
 *
 * 使用方法：
 * 1. 加载此脚本
 * 2. 调用 FloatingMenuManager.init()
 * 3. 使用 FloatingMenuManager.registerButton() 注册功能球
 */

(function() {
    'use strict';

    console.log('[FloatingMenuManager] 脚本开始加载...');

    // ============ 获取父页面 document ============
    const parentDocument = window.parent.document;

    // ============ 配置常量 ============
    const CONFIG = {
        MAIN_SIZE: 56,           // 主球尺寸
        SUB_SIZE: 48,            // 子球尺寸
        SUB_SPACING: 60,         // 子球间距
        DRAG_THRESHOLD: 5,       // 拖拽阈值（px）
        ANIMATION_DURATION: 300, // 动画时长（ms）
        Z_INDEX_MAIN: 10000,     // 主球层级
        Z_INDEX_SUB: 9999,       // 子球层级
        STORAGE_KEY: 'floatingMenuManager_state'
    };

    // ============ SVG 图标 ============
    const ICONS = {
        // 三横线图标（收起状态）
        menu: `<svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
            <path fill-rule="evenodd" d="M2.5 12a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5z"/>
        </svg>`,
        // 向下箭头图标（展开状态）
        chevronDown: `<svg width="20" height="20" viewBox="0 0 16 16" fill="currentColor">
            <path fill-rule="evenodd" d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z"/>
        </svg>`
    };

    // ============ 全局状态 ============
    const state = {
        isExpanded: false,       // 展开状态
        isDragging: false,       // 拖拽状态
        hasMoved: false,         // 是否移动过
        buttons: [],             // 注册的按钮配置
        elements: {              // DOM元素引用
            main: null,          // 主悬浮球
            subContainer: null,  // 子球容器
            subs: []             // 子球数组
        },
        dragData: {              // 拖拽数据
            startX: 0,
            startY: 0,
            initialBottom: 0,
            initialRight: 0
        },
        position: {              // 位置（使用top/left定位）
            top: 100,
            left: 20
        }
    };

    // ============ 样式注入 ============
    function injectStyles() {
        if (parentDocument.getElementById('floating-menu-manager-styles')) return;

        const styles = `
<style id="floating-menu-manager-styles">
/* 主悬浮球 */
.fmm-main-fab {
    position: fixed;
    width: ${CONFIG.MAIN_SIZE}px;
    height: ${CONFIG.MAIN_SIZE}px;
    border-radius: 50%;
    background: linear-gradient(135deg, #4B5563 0%, #374151 100%);
    box-shadow: 0 4px 20px rgba(0,0,0,0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: ${CONFIG.Z_INDEX_MAIN};
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
    color: white;
}

.fmm-main-fab:hover {
    transform: scale(1.1);
    box-shadow: 0 6px 25px rgba(0,0,0,0.4);
}

.fmm-main-fab:active {
    transform: scale(0.95);
}

.fmm-main-fab.dragging {
    cursor: move;
    transform: scale(1.05);
}

.fmm-main-fab .icon {
    transition: transform 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.fmm-main-fab.expanded .icon {
    transform: rotate(180deg);
}

/* 子球容器 */
.fmm-sub-container {
    position: fixed;
    z-index: ${CONFIG.Z_INDEX_SUB};
    pointer-events: none;
}

/* 子悬浮球 */
.fmm-sub-fab {
    position: absolute;
    width: ${CONFIG.SUB_SIZE}px;
    height: ${CONFIG.SUB_SIZE}px;
    border-radius: 50%;
    box-shadow: 0 3px 15px rgba(0,0,0,0.25);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    user-select: none;
    -webkit-user-select: none;
    pointer-events: auto;
    opacity: 0;
    transform: scale(0);
}

.fmm-sub-fab:hover {
    transform: scale(1.1);
    box-shadow: 0 4px 20px rgba(0,0,0,0.35);
}

.fmm-sub-fab:active {
    transform: scale(0.9);
}

/* 展开动画 */
@keyframes fmmExpandBall {
    0% {
        opacity: 0;
        transform: translateY(0) scale(0);
    }
    100% {
        opacity: 1;
        transform: translateY(var(--offset)) scale(1);
    }
}

/* 收起动画 */
@keyframes fmmCollapseBall {
    0% {
        opacity: 1;
        transform: translateY(var(--offset)) scale(1);
    }
    100% {
        opacity: 0;
        transform: translateY(0) scale(0);
    }
}

.fmm-sub-fab.expanding {
    animation: fmmExpandBall ${CONFIG.ANIMATION_DURATION}ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.fmm-sub-fab.collapsing {
    animation: fmmCollapseBall ${CONFIG.ANIMATION_DURATION}ms ease-in forwards;
}
</style>
        `;

        parentDocument.head.insertAdjacentHTML('beforeend', styles);
    }

    // ============ 创建主悬浮球 ============
    function createMainFab() {
        const fab = parentDocument.createElement('div');
        fab.className = 'fmm-main-fab';
        fab.innerHTML = `<div class="icon">${ICONS.menu}</div>`;

        // 设置初始位置
        fab.style.top = state.position.top + 'px';
        fab.style.left = state.position.left + 'px';

        parentDocument.body.appendChild(fab);
        state.elements.main = fab;

        // 绑定事件
        bindMainFabEvents(fab);

        return fab;
    }

    // ============ 创建子球容器 ============
    function createSubContainer() {
        const container = parentDocument.createElement('div');
        container.className = 'fmm-sub-container';
        parentDocument.body.appendChild(container);
        state.elements.subContainer = container;
        return container;
    }

    // ============ 更新子球容器位置 ============
    function updateSubContainerPosition() {
        if (!state.elements.main || !state.elements.subContainer) return;

        const container = state.elements.subContainer;

        // 子球容器位置与主球对齐
        container.style.top = state.position.top + 'px';
        container.style.left = state.position.left + 'px';
        container.style.width = CONFIG.SUB_SIZE + 'px';
        container.style.height = (state.buttons.length * CONFIG.SUB_SPACING) + 'px';
    }

    // ============ 创建子悬浮球 ============
    function createSubFab(config, index) {
        const fab = parentDocument.createElement('div');
        fab.className = 'fmm-sub-fab';
        fab.style.background = config.color || 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)';

        // 设置图标内容
        if (typeof config.icon === 'string') {
            fab.innerHTML = config.icon;
        } else {
            fab.textContent = config.icon || '●';
        }

        // 设置位置偏移
        const offset = -(index + 1) * CONFIG.SUB_SPACING;
        fab.style.setProperty('--offset', offset + 'px');
        fab.style.top = '0px';
        fab.style.left = '4px'; // 居中对齐（(56-48)/2 = 4px）

        // 绑定点击事件
        fab.addEventListener('click', function(e) {
            e.stopPropagation();
            if (config.onClick && typeof config.onClick === 'function') {
                config.onClick();
            }
        });

        state.elements.subContainer.appendChild(fab);
        state.elements.subs.push(fab);

        return fab;
    }

    // ============ 渲染所有子球 ============
    function renderSubFabs() {
        // 清空现有子球
        state.elements.subs.forEach(fab => fab.remove());
        state.elements.subs = [];

        // 创建新的子球
        state.buttons.forEach((config, index) => {
            createSubFab(config, index);
        });

        updateSubContainerPosition();
    }

    // ============ 展开菜单 ============
    function expand() {
        if (state.isExpanded) return;
        state.isExpanded = true;

        // 更新主球图标
        const icon = state.elements.main.querySelector('.icon');
        icon.innerHTML = ICONS.chevronDown;
        state.elements.main.classList.add('expanded');

        // 展开子球
        state.elements.subs.forEach((fab, index) => {
            fab.classList.remove('collapsing');
            fab.classList.add('expanding');

            // 延迟显示，创造级联效果
            setTimeout(() => {
                fab.style.opacity = '1';
                fab.style.transform = `translateY(${-(index + 1) * CONFIG.SUB_SPACING}px) scale(1)`;
            }, index * 50);
        });
    }

    // ============ 收起菜单 ============
    function collapse() {
        if (!state.isExpanded) return;
        state.isExpanded = false;

        // 更新主球图标
        const icon = state.elements.main.querySelector('.icon');
        icon.innerHTML = ICONS.menu;
        state.elements.main.classList.remove('expanded');

        // 收起子球
        state.elements.subs.forEach((fab, index) => {
            fab.classList.remove('expanding');
            fab.classList.add('collapsing');

            setTimeout(() => {
                fab.style.opacity = '0';
                fab.style.transform = 'translateY(0) scale(0)';
            }, index * 30);
        });
    }

    // ============ 切换展开/收起 ============
    function toggle() {
        if (state.isExpanded) {
            collapse();
        } else {
            expand();
        }
    }

    // ============ 主球拖拽事件 ============
    function bindMainFabEvents(fab) {
        let rafId = null;

        function handleStart(e) {
            const touch = e.touches ? e.touches[0] : e;
            state.isDragging = true;
            state.hasMoved = false;
            state.dragData.startX = touch.clientX;
            state.dragData.startY = touch.clientY;

            const rect = fab.getBoundingClientRect();
            state.dragData.initialTop = rect.top;
            state.dragData.initialLeft = rect.left;

            fab.classList.add('dragging');
            e.preventDefault();
        }

        function handleMove(e) {
            if (!state.isDragging) return;

            const touch = e.touches ? e.touches[0] : e;
            const deltaX = touch.clientX - state.dragData.startX;
            const deltaY = touch.clientY - state.dragData.startY;

            // 判断是否移动
            if (Math.abs(deltaX) > CONFIG.DRAG_THRESHOLD || Math.abs(deltaY) > CONFIG.DRAG_THRESHOLD) {
                state.hasMoved = true;
            }

            // 使用 RAF 优化性能
            if (rafId) cancelAnimationFrame(rafId);
            rafId = requestAnimationFrame(() => {
                const newLeft = Math.max(0, Math.min(
                    state.dragData.initialLeft + deltaX,
                    window.parent.innerWidth - CONFIG.MAIN_SIZE
                ));
                const newTop = Math.max(0, Math.min(
                    state.dragData.initialTop + deltaY,
                    window.parent.innerHeight - CONFIG.MAIN_SIZE
                ));

                state.position.left = newLeft;
                state.position.top = newTop;

                fab.style.left = newLeft + 'px';
                fab.style.top = newTop + 'px';

                // 更新子球容器位置
                updateSubContainerPosition();

                rafId = null;
            });

            e.preventDefault();
        }

        function handleEnd(e) {
            if (!state.isDragging) return;
            state.isDragging = false;
            fab.classList.remove('dragging');

            // 保存位置
            savePosition();

            // 如果没有移动，则视为点击
            if (!state.hasMoved) {
                toggle();
            }

            state.hasMoved = false;
            e.preventDefault();
        }

        // 鼠标事件
        fab.addEventListener('mousedown', handleStart);
        parentDocument.addEventListener('mousemove', handleMove);
        parentDocument.addEventListener('mouseup', handleEnd);

        // 触摸事件
        fab.addEventListener('touchstart', handleStart, { passive: false });
        parentDocument.addEventListener('touchmove', handleMove, { passive: false });
        parentDocument.addEventListener('touchend', handleEnd, { passive: false });
    }

    // ============ 位置持久化 ============
    function savePosition() {
        try {
            const data = {
                top: state.position.top,
                left: state.position.left,
                isExpanded: state.isExpanded
            };
            localStorage.setItem(CONFIG.STORAGE_KEY, JSON.stringify(data));
        } catch (e) {
            console.error('[FloatingMenuManager] 保存位置失败:', e);
        }
    }

    function loadPosition() {
        try {
            const saved = localStorage.getItem(CONFIG.STORAGE_KEY);
            if (saved) {
                const data = JSON.parse(saved);
                state.position.top = data.top || 100;
                state.position.left = data.left || 20;
                // 不恢复展开状态，始终从收起状态开始
            }
        } catch (e) {
            console.error('[FloatingMenuManager] 加载位置失败:', e);
        }
    }

    // ============ 调整位置到可见范围 ============
    function adjustPositionToViewport() {
        if (!state.elements.main) return;

        const maxLeft = window.parent.innerWidth - CONFIG.MAIN_SIZE;
        const maxTop = window.parent.innerHeight - CONFIG.MAIN_SIZE;

        // 确保悬浮球在可见范围内
        let adjusted = false;

        if (state.position.left > maxLeft) {
            state.position.left = Math.max(0, maxLeft);
            adjusted = true;
        }

        if (state.position.top > maxTop) {
            state.position.top = Math.max(0, maxTop);
            adjusted = true;
        }

        if (state.position.left < 0) {
            state.position.left = 0;
            adjusted = true;
        }

        if (state.position.top < 0) {
            state.position.top = 0;
            adjusted = true;
        }

        // 如果位置被调整，更新DOM和保存
        if (adjusted) {
            state.elements.main.style.left = state.position.left + 'px';
            state.elements.main.style.top = state.position.top + 'px';
            updateSubContainerPosition();
            savePosition();
        }
    }

    // ============ 窗口大小改变监听 ============
    function bindWindowResize() {
        let resizeTimer = null;
        window.parent.addEventListener('resize', function() {
            // 使用防抖，避免频繁调整
            if (resizeTimer) clearTimeout(resizeTimer);
            resizeTimer = setTimeout(function() {
                adjustPositionToViewport();
                resizeTimer = null;
            }, 100);
        });
    }

    // ============ 公共API ============
    const FloatingMenuManager = {
        /**
         * 注册子按钮
         * @param {Object} config - 按钮配置
         * @param {string} config.id - 按钮唯一ID
         * @param {string|HTMLElement} config.icon - 图标（可以是emoji、SVG字符串或HTML）
         * @param {string} config.label - 按钮标签（用于调试）
         * @param {Function} config.onClick - 点击回调函数
         * @param {string} config.color - 背景渐变色
         * @param {number} config.order - 排序顺序（可选，默认按注册顺序）
         */
        registerButton: function(config) {
            if (!config || !config.id) {
                console.error('[FloatingMenuManager] 注册失败：缺少必要参数 id');
                return false;
            }

            // 检查是否已注册
            const existingIndex = state.buttons.findIndex(btn => btn.id === config.id);
            if (existingIndex !== -1) {
                console.warn('[FloatingMenuManager] 按钮已存在，将更新配置:', config.id);
                state.buttons[existingIndex] = config;
            } else {
                state.buttons.push(config);
            }

            // 按order排序
            state.buttons.sort((a, b) => (a.order || 99) - (b.order || 99));

            // 重新渲染子球
            if (state.elements.subContainer) {
                renderSubFabs();
            }

            console.log('[FloatingMenuManager] 注册成功:', config.id);
            return true;
        },

        /**
         * 取消注册按钮
         * @param {string} id - 按钮ID
         */
        unregisterButton: function(id) {
            const index = state.buttons.findIndex(btn => btn.id === id);
            if (index !== -1) {
                state.buttons.splice(index, 1);
                if (state.elements.subContainer) {
                    renderSubFabs();
                }
                console.log('[FloatingMenuManager] 取消注册:', id);
                return true;
            }
            return false;
        },

        /**
         * 展开菜单
         */
        expand: function() {
            expand();
        },

        /**
         * 收起菜单
         */
        collapse: function() {
            collapse();
        },

        /**
         * 切换展开/收起
         */
        toggle: function() {
            toggle();
        },

        /**
         * 初始化管理器
         */
        init: function() {
            console.log('[FloatingMenuManager] 初始化...');

            // 清理旧实例
            this.destroy();

            // 加载保存的位置
            loadPosition();

            // 注入样式
            injectStyles();

            // 创建主悬浮球
            createMainFab();

            // 创建子球容器
            createSubContainer();

            // 处理模块先于FMM加载时的待注册队列
            var pending = window.parent._fmmPendingRegistrations;
            if (pending && pending.length) {
                pending.forEach(function(config) {
                    FloatingMenuManager.registerButton(config);
                });
                window.parent._fmmPendingRegistrations = [];
                console.log('[FloatingMenuManager] 处理了 ' + pending.length + ' 个待注册按钮');
            }

            // 渲染已注册的子球
            renderSubFabs();

            // 调整位置到可见范围
            adjustPositionToViewport();

            // 绑定窗口大小改变监听
            bindWindowResize();

            console.log('[FloatingMenuManager] 初始化完成');
        },

        /**
         * 销毁管理器
         */
        destroy: function() {
            // 移除DOM元素（通过state引用）
            if (state.elements.main) {
                state.elements.main.remove();
                state.elements.main = null;
            }
            if (state.elements.subContainer) {
                state.elements.subContainer.remove();
                state.elements.subContainer = null;
            }

            // 通过选择器清理孤儿元素（脚本重执行时旧state已丢失）
            parentDocument.querySelectorAll('.fmm-main-fab').forEach(function(el) { el.remove(); });
            parentDocument.querySelectorAll('.fmm-sub-container').forEach(function(el) { el.remove(); });

            // 移除注入的样式
            const styles = parentDocument.getElementById('floating-menu-manager-styles');
            if (styles) styles.remove();

            // 清空子球数组
            state.elements.subs = [];

            // 清空注册的按钮
            state.buttons = [];

            // 重置状态
            state.isExpanded = false;
            state.isDragging = false;
            state.hasMoved = false;

            console.log('[FloatingMenuManager] 已销毁');
        },

        /**
         * 获取当前状态
         */
        getState: function() {
            return {
                isExpanded: state.isExpanded,
                buttonCount: state.buttons.length,
                position: { ...state.position }
            };
        },

        /**
         * 获取已注册的按钮列表
         */
        getButtons: function() {
            return state.buttons.map(btn => ({
                id: btn.id,
                label: btn.label,
                order: btn.order
            }));
        }
    };

    // ============ 导出到全局 ============
    if (typeof window !== 'undefined') {
        window.parent.FloatingMenuManager = FloatingMenuManager;
        console.log('[FloatingMenuManager] 已加载到 window.parent.FloatingMenuManager');
    }

    // ============ 自动初始化 ============
    if (parentDocument.readyState === 'loading') {
        parentDocument.addEventListener('DOMContentLoaded', function() {
            FloatingMenuManager.init();
        });
    } else {
        FloatingMenuManager.init();
    }

    // ============ 自动清理 ============
    $(window).on('pagehide', function() {
        console.log('[FloatingMenuManager] 脚本卸载，执行清理...');
        FloatingMenuManager.destroy();
    });

})();

/**
 * 脚本预设管理器 — 自定义脚本组合，一键切换
 *
 * 功能：
 * - 扫描酒馆助手中所有脚本（全局/预设/角色卡）
 * - 让用户勾选想要启用的脚本，保存为"预设"
 * - 支持创建、编辑、删除多套预设
 * - 一键应用预设（批量开关脚本 + 正则）
 * - 集成 FloatingMenuManager 悬浮球
 *
 * 依赖：
 * - 酒馆助手 API: getScriptTrees / updateScriptTreesWith
 * - 酒馆助手 API: getTavernRegexes / updateTavernRegexesWith（可选）
 * - FloatingMenuManager（可选）
 */

(function () {
    'use strict';

    // ================================================================
    // 常量
    // ================================================================
    const MODULE = 'ScriptPresetManager';
    const STORAGE_KEY = 'spm_presets';
    const ACTIVE_KEY  = 'spm_active';
    const OVERLAY_ID  = 'spm-overlay';
    const PANEL_ID    = 'spm-panel';
    const parentDoc   = window.parent.document;

    // ================================================================
    // 内置预设（基于脚本名称模式匹配，可跨安装移植）
    // ================================================================
    //
    // 规则按顺序匹配，第一个命中的规则生效。
    // 未命中任何规则的脚本使用 defaultEnabled 的值。
    // 导出角色卡时这些预设会随脚本一起打包，别人导入后即可直接使用。
    //
    // ★ 用户可根据实际脚本名称自行增删 rules ★

    const BUILTIN_PRESETS = [
        {
            id: '_builtin_original',
            name: '原版',
            icon: '📦',
            builtin: true,
            description: '使用原版脚本，禁用二改版',
            rules: [
                // ——— 二改版脚本一律禁用 ———
                { match: '二改版',       enabled: false },
                { match: '二创',         enabled: false },
                // ——— 始终禁用 ———
                { match: '悬浮球示例',   enabled: false },
                { match: '美化完整修复版', enabled: false },
            ],
            defaultEnabled: true,
            regexRules: [],
            defaultRegexEnabled: true,
        },
        {
            id: '_builtin_fancreation',
            name: '二创版',
            icon: '🎨',
            builtin: true,
            description: '使用二改版脚本，禁用被替代的原版',
            rules: [
                // ——— 最高优先级：二改版脚本启用 ———
                { match: '二改版', enabled: true },
                { match: '二创',   enabled: true },
                // ——— 被 公寓（二改版）替代 ———
                { match: '公寓',   enabled: false },
                // ——— 被 租客分析系统（二改版）替代 ———
                { match: '租客分析系统', enabled: false },
                { match: '分析调度器',   enabled: false },
                { match: '分析队列',     enabled: false },
                { match: '租客档案',     enabled: false },
                // ——— 被 聊天系统（二改版）替代 ———
                { match: '聊天数据库',   enabled: false },
                { match: '聊天核心',     enabled: false },
                { match: '聊天正文',     enabled: false },
                { match: '聊天APP',      enabled: false },
                // ——— 被 音乐（二改版）替代 ———
                { match: '音乐',         enabled: false },
                // ——— 小手机系统（二创版不使用） ———
                { match: '小手机',       enabled: false },
                { match: '提示词',       enabled: false },
                { match: '地图',         enabled: false },
                { match: '天气',         enabled: false },
                { match: '新闻',         enabled: false },
                { match: '和欧欧',       enabled: false },
                // ——— 始终禁用 ———
                { match: '悬浮球示例',   enabled: false },
                { match: '美化完整修复版', enabled: false },
            ],
            defaultEnabled: true,
            regexRules: [],
            defaultRegexEnabled: true,
        },
    ];

    /** 判断是否为内置预设 */
    function isBuiltin(preset) {
        return !!(preset && preset.builtin);
    }

    /** 获取内置+用户预设的合并列表（内置在前） */
    function getAllPresets() {
        return [...BUILTIN_PRESETS, ...loadPresets()];
    }

    // ================================================================
    // 数据层：预设的 CRUD
    // ================================================================

    /**
     * 预设结构:
     * {
     *   id: string,           // uuid
     *   name: string,         // 用户取的名字
     *   icon: string,         // emoji
     *   scripts: {            // 脚本快照 { [scriptId]: boolean }
     *     'xxx-uuid': true,   // 启用
     *     'yyy-uuid': false,  // 禁用
     *   },
     *   regexes: {            // 正则快照 { [regexId]: boolean }（可选）
     *     'zzz-uuid': true,
     *   },
     *   createdAt: number,
     * }
     */

    function loadPresets() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            return raw ? JSON.parse(raw) : [];
        } catch (e) {
            console.error(`[${MODULE}] 读取预设失败:`, e);
            return [];
        }
    }

    function savePresets(presets) {
        try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(presets));
        } catch (e) {
            console.error(`[${MODULE}] 保存预设失败:`, e);
        }
    }

    function getActivePresetId() {
        try { return localStorage.getItem(ACTIVE_KEY) || ''; } catch (e) { return ''; }
    }

    function setActivePresetId(id) {
        try { localStorage.setItem(ACTIVE_KEY, id); } catch (e) {}
    }

    function generateId() {
        return 'spm_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    }

    // ================================================================
    // 扫描当前脚本 / 正则
    // ================================================================

    /**
     * 获取所有脚本的扁平列表
     * @returns {{ id:string, name:string, enabled:boolean, type:'script'|'folder', parentFolder?:string }[]}
     */
    function getAllScripts() {
        const list = [];
        try {
            const trees = getScriptTrees({ type: 'character' });
            trees.forEach(item => {
                if (item.type === 'script') {
                    list.push({ id: item.id, name: item.name, enabled: item.enabled, type: 'script' });
                } else if (item.type === 'folder') {
                    list.push({ id: item.id, name: item.name, enabled: item.enabled, type: 'folder' });
                    if (item.scripts) {
                        item.scripts.forEach(sub => {
                            list.push({ id: sub.id, name: sub.name, enabled: sub.enabled, type: 'script', parentFolder: item.name });
                        });
                    }
                }
            });
        } catch (e) {
            console.error(`[${MODULE}] 获取脚本列表失败:`, e);
        }
        return list;
    }

    /**
     * 获取所有正则的扁平列表
     */
    function getAllRegexes() {
        try {
            return getTavernRegexes({ type: 'character' });
        } catch (e) {
            console.warn(`[${MODULE}] 获取正则列表失败:`, e.message);
            return [];
        }
    }

    /**
     * 从当前环境创建快照
     */
    function snapshotCurrent() {
        const scripts = {};
        getAllScripts().forEach(s => { scripts[s.id] = s.enabled; });
        const regexes = {};
        getAllRegexes().forEach(r => { regexes[r.id] = r.enabled; });
        return { scripts, regexes };
    }

    // ================================================================
    // 核心：应用预设
    // ================================================================

    /**
     * 应用用户预设（基于脚本ID匹配）
     */
    async function applyPreset(preset) {
        console.log(`[${MODULE}] 应用预设: ${preset.name}`);

        // 内置预设走名称匹配逻辑
        if (isBuiltin(preset)) {
            return await applyBuiltinPreset(preset);
        }

        const disabledNames = [];

        // 1. 脚本
        try {
            const allScripts = getAllScripts();
            const nameById = {};
            allScripts.forEach(sc => { nameById[sc.id] = sc.name; });

            updateScriptTreesWith((trees) => {
                function toggle(item) {
                    if (item.id in preset.scripts) {
                        item.enabled = preset.scripts[item.id];
                        if (!preset.scripts[item.id] && item.name) disabledNames.push(item.name);
                    }
                    if (item.type === 'folder' && item.scripts) {
                        item.scripts.forEach(sub => toggle(sub));
                    }
                }
                trees.forEach(t => toggle(t));
                return trees;
            }, { type: 'character' });
        } catch (e) {
            console.error(`[${MODULE}] 脚本切换失败:`, e);
            throw e;
        }

        // 2. 正则（可选）
        if (preset.regexes && Object.keys(preset.regexes).length > 0) {
            try {
                await updateTavernRegexesWith((regexes) => {
                    regexes.forEach(r => {
                        if (r.id in preset.regexes) {
                            r.enabled = preset.regexes[r.id];
                        }
                    });
                    return regexes;
                }, { type: 'character' });
            } catch (e) {
                console.warn(`[${MODULE}] 正则切换跳过:`, e.message);
            }
        }

        setActivePresetId(preset.id);
        cleanupByDisabledNames(disabledNames);
        console.log(`[${MODULE}] 预设 "${preset.name}" 已应用`);
    }

    /**
     * 应用内置预设（基于脚本名称模式匹配，可跨安装移植）
     */
    async function applyBuiltinPreset(builtin) {
        console.log(`[${MODULE}] 应用内置预设: ${builtin.name}`);
        const disabledNames = [];

        // 1. 脚本 — 按 rules 顺序匹配名称
        try {
            updateScriptTreesWith((trees) => {
                function toggle(item) {
                    const name = item.name || '';
                    let matched = false;
                    for (const rule of builtin.rules) {
                        if (name.includes(rule.match)) {
                            item.enabled = rule.enabled;
                            if (!rule.enabled) disabledNames.push(name);
                            matched = true;
                            break;
                        }
                    }
                    if (!matched) {
                        item.enabled = builtin.defaultEnabled;
                        if (!builtin.defaultEnabled) disabledNames.push(name);
                    }
                    if (item.type === 'folder' && item.scripts) {
                        item.scripts.forEach(sub => toggle(sub));
                    }
                }
                trees.forEach(t => toggle(t));
                return trees;
            }, { type: 'character' });
        } catch (e) {
            console.error(`[${MODULE}] 脚本切换失败:`, e);
            throw e;
        }

        // 2. 正则（可选）
        if (builtin.regexRules && builtin.regexRules.length > 0) {
            try {
                await updateTavernRegexesWith((regexes) => {
                    regexes.forEach(r => {
                        const name = r.script_name || '';
                        let matched = false;
                        for (const rule of builtin.regexRules) {
                            if (name.includes(rule.match)) {
                                r.enabled = rule.enabled;
                                matched = true;
                                break;
                            }
                        }
                        if (!matched && builtin.defaultRegexEnabled !== undefined) {
                            r.enabled = builtin.defaultRegexEnabled;
                        }
                    });
                    return regexes;
                }, { type: 'character' });
            } catch (e) {
                console.warn(`[${MODULE}] 正则切换跳过:`, e.message);
            }
        }

        setActivePresetId(builtin.id);
        cleanupByDisabledNames(disabledNames);
        console.log(`[${MODULE}] 内置预设 "${builtin.name}" 已应用`);
    }

    /**
     * 根据被禁用的脚本名称列表，调用清理函数 + 反注册FMM按钮
     */
    function cleanupByDisabledNames(disabledNames) {
        const CLEANUP_MAP = [
            { patterns: ['大富翁', 'monopoly', 'monopoly_main', '棋盘'], fn: 'cleanupMonopolyPlugin', fmmId: 'monopoly' },
            { patterns: ['掌上公寓', 'apartment', '公寓'], fn: 'cleanupApartmentPlugin', fmmId: 'apartment' },
            { patterns: ['创意工坊', 'workshop', '工坊'], fn: 'cleanupWorkshopPlugin', fmmId: 'workshop' },
            { patterns: ['手机', 'phone', '小手机', 'phone_main'], fn: 'cleanupPhone', fmmId: 'phone' },
        ];

        console.log(`[${MODULE}] 被禁用的脚本:`, disabledNames);
        const fmm = window.parent.FloatingMenuManager;

        CLEANUP_MAP.forEach(({ patterns, fn, fmmId }) => {
            const shouldClean = disabledNames.some(name =>
                patterns.some(p => name.toLowerCase().includes(p.toLowerCase()))
            );
            if (shouldClean) {
                try {
                    if (typeof window[fn] === 'function') {
                        window[fn]();
                        console.log(`[${MODULE}] 已调用 ${fn}() 清理`);
                    } else if (typeof window.parent[fn] === 'function') {
                        window.parent[fn]();
                        console.log(`[${MODULE}] 已调用 parent.${fn}() 清理`);
                    }
                } catch (e) {
                    console.warn(`[${MODULE}] 调用 ${fn}() 失败:`, e.message);
                }
                try {
                    if (fmm && typeof fmm.unregisterButton === 'function') {
                        fmm.unregisterButton(fmmId);
                    }
                } catch (e) {}
            }
        });
    }

