function fillCommand(command) {
    try {
        const chatInput = parent.document.querySelector('#send_textarea');
        if (chatInput) {
            if (chatInput.value.trim() !== '') {
                chatInput.value += '\n' + command;
            } else {
                chatInput.value = command;
            }
            chatInput.focus();
        } else {
            throw new Error();
        }
    } catch (e) {
        alert('未能自动找到输入框，请手动复制：\n\n' + command);
    }
}

