                // 恢复刷新按钮（检查元素是否仍存在）
                const currentRefreshBtn = iframeDoc?.getElementById?.('news-refresh-btn');
                if (currentRefreshBtn) {
                    currentRefreshBtn.disabled = false;
                    currentRefreshBtn.innerHTML = '刷新';
                    currentRefreshBtn.style.opacity = '1';
                }
            }
