    // 生成单条消息HTML
    function generateMessageHTML(msg) {
        const isUser = msg.sender === 'user';
        const avatarUrl = isUser ? getUserAvatarPath() : OC_CONFIG.avatar;
        const defaultAvatar = isUser 
            ? 'https://api.iconify.design/ri:user-3-fill.svg?color=%23999'
