        return `
            <div class="chat-message ${isUser ? 'self' : 'other'}" data-msg-id="${msg.id}">
                <div class="msg-avatar" style="background-image: url('${avatarUrl || defaultAvatar}'); background-size: cover;"></div>
                <div class="msg-content-wrap">
