// 表情包专用列表（带内存缓存）
async function wsCloudStickerList(page, sort) {
    page = page || 1; sort = sort || 'newest';
    var cacheKey = wsCloudCacheKey('sticker', page, sort);
    var cached = wsCloudCacheGet(cacheKey);
    if (cached) return cached;
