    }

    manualZoneOverride = false; // 掷骰后自动跟随玩家位置

    // 新回合开始：清理上一轮残留的场景指令
    clearSceneLore().catch(() => {});
    _pendingSceneLore = false;
    if (_sceneLoreSafetyTimer) { clearTimeout(_sceneLoreSafetyTimer); _sceneLoreSafetyTimer = null; }

    // 指定骰buff：弹出选择面板
    if (activeBuffs.指定骰) {
        activeBuffs.指定骰 = false;
