<script>
(function() {
    const rawData = document.getElementById('raw-data').textContent;
    const candidatesContainer = document.getElementById('candidates-container');
    const confirmButton = document.getElementById('confirm-button');
    let selectedCandidateNames = [];

    if (!rawData || rawData.trim() === '') return;
    candidatesContainer.innerHTML = '';

    const candidates = rawData.split('候选人:').slice(1);
    if (candidates.length === 0) {
        candidatesContainer.innerHTML = '<p class="loading-text" style="color: #ec4899;">❓ 没有找到有效的候选人数据</p>';
        return;
    }

    candidates.forEach(candidateText => {
        const extract = (key) => { const regex = new RegExp(key + ': "([^"]+)"'); const match = candidateText.match(regex); return match ? match[1] : ''; };
        const name = extract('名字');
        if (!name) return;

        const card = document.createElement('div');
        card.className = 'candidate-card';
        card.onclick = () => handleCardClick(card, name);

        let tagsHTML = '';
        const tags = extract('标签');
        if (tags) { tags.split('/').forEach(tag => { tagsHTML += '<span class="tag">' + tag.trim() + '</span>'; }); }

        const brief = extract('简介');
        card.innerHTML = '<div class="candidate-name">' + name + '</div>' +
            '<div class="tags-container">' + tagsHTML + '</div>' +
            '<div class="details"><div>🎂 ' + extract('年龄') + ' | 👗 ' + extract('常见穿搭') + '</div>' +
            '<div style="margin-top:2px">❤️ ' + extract('情感状况') + '</div>' +
            (brief ? '<div style="margin-top:4px">📝 ' + brief + '</div>' : '') + '</div>' +
            '<div class="quote">"' + extract('代表性发言') + '"</div>';
        candidatesContainer.appendChild(card);
    });

    function handleCardClick(clickedCard, candidateName) {
        const isAlreadySelected = clickedCard.classList.contains('selected');
        if (isAlreadySelected) {
            clickedCard.classList.remove('selected');
            selectedCandidateNames = selectedCandidateNames.filter(n => n !== candidateName);
        } else {
            if (selectedCandidateNames.length >= 2) { alert('最多入住2人哦！'); return; }
            clickedCard.classList.add('selected');
            selectedCandidateNames.push(candidateName);
        }
        updateConfirmButtonState();
    }

    function updateConfirmButtonState() {
        if (selectedCandidateNames.length > 0) {
            confirmButton.classList.remove('disabled');
            confirmButton.textContent = '确认入住 (' + selectedCandidateNames.length + '/2)';
        } else {
            confirmButton.classList.add('disabled');
            confirmButton.textContent = '请先选择候选人';
        }
    }

    confirmButton.onclick = function() {
        if (!this.classList.contains('disabled') && selectedCandidateNames.length > 0) {
            const namesText = selectedCandidateNames.map(n => '"' + n + '"').join('和');
            const message = '我选择 ' + namesText + ' 作为新租客。请为' + (selectedCandidateNames.length === 1 ? '这位租客' : '这些租客') + '生成详细的固定信息（性格、背景、爱好等不变的特征），用于添加到Chat Lore。';
            if (typeof triggerSlash === 'function') {
                triggerSlash('/send ' + message.trim() + '|/trigger');
            } else {
                alert('模拟发送：\n' + message);
            }
            this.textContent = '✅ 已提交申请';
            this.classList.add('disabled');
        }
    };
})();
</script>
