    const nameRegex = /姓名[：:]\s*([^\n\r]+)/g;
    const names = [];
    let match;
    while ((match = nameRegex.exec(rawData)) !== null) {
        names.push(match[1].trim());
    }

    if (names.length === 0) {
        tenantsContainer.innerHTML = '<div class="loading" style="color: #ec4899; background: #fff1f2; border-color: #fda4af;">❌ 数据解析异常</div>';
        return;
    }

    if (names.length === 1) {
        tenantsData.push({ name: names[0], content: rawData.trim() });
    } else {
        const blocks = rawData.split(/基本信息[：:]/);
        for (let i = 1; i < blocks.length && i - 1 < names.length; i++) {
            tenantsData.push({ name: names[i - 1], content: '基本信息：' + blocks[i].trim() });
        }
    }

    tenantsContainer.innerHTML = '';
    tenantsData.forEach(function(tenant, index) {
        const card = document.createElement('div');
        card.className = 'tenant-card';
        card.innerHTML = '<div class="tenant-name"><i class="fa fa-user-circle"></i> ' + tenant.name + '</div>' +
            '<div class="edit-area" id="tenant-content-' + index + '" contenteditable="true">' + tenant.content + '</div>' +
            '<div class="hint-text"><i class="fa fa-info-circle"></i> 将保存为 World Info (Constant)</div>';
        tenantsContainer.appendChild(card);
    });

    addAllBtn.classList.remove('disabled');
    confirmMoveInBtn.classList.remove('disabled');

    addAllBtn.addEventListener('click', async function() {
        var btn = this;
        // 查找酒馆助手API（遍历parent链，兼容iframe嵌套）
        var getOrCreate = null, updateWB = null;
        var w = window;
        for (var depth = 0; depth < 5 && w; depth++) {
            if (typeof w.getOrCreateChatWorldbook === 'function') getOrCreate = w.getOrCreateChatWorldbook;
            if (typeof w.updateWorldbookWith === 'function') updateWB = w.updateWorldbookWith;
            if (getOrCreate && updateWB) break;
            try { w = w.parent; } catch(e) { break; }
            if (w === window) break;
        }
        if (getOrCreate && updateWB) {
            try {
                var loreName = await getOrCreate('current');
                if (!loreName) { alert('无法创建ChatLore'); return; }
                var successCount = 0;
                for (var i = 0; i < tenantsData.length; i++) {
                    var content = document.getElementById('tenant-content-' + i).textContent.trim();
                    var name = tenantsData[i].name;
                    if (content && name) {
                        await updateWB(loreName, function(entries) {
                            var idx = entries.findIndex(function(e) { return e.name === name; });
                            var entry = {
                                name: name, enabled: true, content: content,
                                strategy: { type: 'constant', keys: [name], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
                                position: { type: 'before_character_definition', role: 'system', depth: 4, order: 100 },
                                probability: 100
                            };
                            if (idx >= 0) entries[idx] = Object.assign({}, entries[idx], entry); else entries.push(entry);
                            return entries;
                        });
                        successCount++;
                    }
                }
                btn.innerHTML = '<i class="fa fa-check"></i> 已保存';
                btn.classList.add('disabled');
                if (successCount > 0) alert('✅ ' + successCount + ' 份档案已归档（蓝灯常驻）！');
            } catch(e) { alert('保存失败: ' + e.message); }
        } else if (typeof triggerSlash === 'function') {
            var successCount = 0;
            tenantsData.forEach(function(tenant, index) {
                var content = document.getElementById('tenant-content-' + index).textContent.trim();
                if (content) {
                    triggerSlash('/getchatbook | /createentry file={{pipe}} key=' + tenant.name + ' ' + content);
                    setTimeout(function() { triggerSlash('/getchatbook | /setentryfield file={{pipe}} key=' + tenant.name + ' field=constant true'); }, 200 * (index + 1));
                    successCount++;
                }
            });
            if (successCount > 0) {
                btn.innerHTML = '<i class="fa fa-check"></i> 已保存';
                btn.classList.add('disabled');
                alert('✅ ' + successCount + ' 份档案已归档！');
            }
        } else {
            alert('请在酒馆中运行');
        }
    });

    // 办理入住 → 展开房间选择器
    var roomPicker = document.getElementById('room-picker');
    var roomGrid = document.getElementById('room-grid');
    var roomFallback = document.getElementById('room-picker-fallback');
    var confirmRoomBtn = document.getElementById('confirm-room-btn');
    var selectedRoomKey = '';
    var selectedRoomOccupant = '';

    confirmMoveInBtn.addEventListener('click', function() {
        if (roomPicker.classList.contains('active')) {
            roomPicker.classList.remove('active');
            return;
        }
        // 尝试从掌上公寓获取卧室列表
        var bedrooms = [];
        try { bedrooms = parent.getApartmentBedrooms ? parent.getApartmentBedrooms() : []; } catch(e) {}

        roomGrid.innerHTML = '';
        if (bedrooms.length > 0) {
            roomFallback.style.display = 'none';
            bedrooms.forEach(function(r, i) {
                var badgeClass = r.isEmpty ? 'badge-empty' : 'badge-occupied';
                var badgeText = r.isEmpty ? '✅ 空闲' : '🏠 ' + r.occupant;
                var card = document.createElement('div');
                card.className = 'room-card';
                card.dataset.key = r.key;
                card.dataset.occupant = r.isEmpty ? '' : r.occupant;
                card.innerHTML = '<div class="room-card-name">' + r.name + '</div>'
                    + '<div class="room-card-info">' + r.floor + ' · ' + r.position + '</div>'
                    + '<span class="room-card-badge ' + badgeClass + '">' + badgeText + '</span>';
                card.addEventListener('click', function() {
                    roomGrid.querySelectorAll('.room-card').forEach(function(c) { c.classList.remove('rc-selected'); });
                    card.classList.add('rc-selected');
                    selectedRoomKey = r.key;
                    selectedRoomOccupant = r.isEmpty ? '' : r.occupant;
                    confirmRoomBtn.classList.remove('disabled');
                    confirmRoomBtn.innerHTML = '<i class="fa fa-check"></i> 入住 → ' + r.name;
                });
                roomGrid.appendChild(card);
            });
            // 默认选中第一个空闲卧室，没有空闲则选第一个
            var autoSelect = roomGrid.querySelector('.room-card[data-occupant=""]') || roomGrid.querySelector('.room-card');
            if (autoSelect) autoSelect.click();
        } else {
            roomGrid.innerHTML = '<div class="room-picker-none">⚠️ 无法获取卧室数据，请手动输入</div>';
